#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { assertQuoteReconciles, computeWaterfall } from '@platform/contracts';

/**
 * CI gate: money-reconciliation (§5.4/§5.5, standing guardrail) — runs the
 * PINNED assertQuoteReconciles over a quote-money fixture file. The positive
 * fixture is the §5.4 worked baseline generated by the pinned
 * computeWaterfall; the negative fixture carries an independent-
 * multiplication sellerNet that drifts one franc. Exact to the franc.
 *
 * ── AUDIT-B+1 F8: THE IDENTITIES ALONE CANNOT SEE A WRONG FEE RATE ─────────
 * `assertQuoteReconciles` checks three IDENTITIES:
 *   productSubtotal == sellerNet + resellerNet + platformProductFeeRevenue
 *   buyerTotal      == productSubtotal + deliveryFee
 *   paidAtCheckout + dueAtDelivery == buyerTotal
 * All three hold for ANY split of `B + M`. Reproduced before writing this: a
 * quote taking **20 % from the seller instead of the pinned 5 %** — sellerNet
 * 7 000 instead of 8 500, with 1 500 FCFA moved to the platform — satisfies
 * every identity and the gate exited 0. Law 1 says the model reconciles AND
 * that the seller fee is 5 %·B; the identities only ever tested the first half.
 *
 * So the gate now also RECOMPUTES the quote from its own inputs (B, C, M, D,
 * paymentMode) through the pinned `computeWaterfall` and compares field by
 * field. The rates come from the same pinned RoundingLaw the product uses, so
 * this is not a second implementation of the money model — it is the gate
 * finally asking the pinned one what the answer should be.
 *
 * NOT DONE HERE, deliberately: no re-derivation of the fee percentages in this
 * file. A gate that hard-codes 5 % would drift from canon the day canon moves,
 * and would be a second money model — which §7 reserves to the founder.
 */
const file = process.argv[2];
if (!file) {
  console.error('usage: money-reconciliation.mjs <quote-money.json>');
  process.exit(2);
}
let quote;
try {
  quote = JSON.parse(readFileSync(file, 'utf8'));
} catch (err) {
  // exit 2 = the gate could not run — never confusable with a gate failure (1)
  console.error(`money-reconciliation: cannot read fixture ${file}: ${String(err)}`);
  process.exit(2);
}
try {
  assertQuoteReconciles(quote);
} catch (err) {
  console.error(`money-reconciliation FAILED on ${file}:`);
  console.error(String(err.message ?? err));
  process.exit(1);
}

/* F8 — the identities passed; now ask the PINNED waterfall what this quote's
 * own inputs should have produced, and compare every field to the franc. */
const INPUTS = ['sellerBasePrice', 'sellerFundedCommission', 'resellerMarkup', 'deliveryFee', 'paymentMode'];
const manquants = INPUTS.filter((k) => quote[k] === undefined);
if (manquants.length > 0) {
  // exit 2 = the gate could not run — a fixture without inputs cannot be
  // recomputed, and silently skipping the rate check would restore the defect.
  console.error(`money-reconciliation: ${file} lacks the inputs needed to recompute: ${manquants.join(', ')}`);
  process.exit(2);
}

let attendu;
try {
  attendu = computeWaterfall(quote);
} catch (err) {
  console.error(`money-reconciliation FAILED on ${file}: the pinned waterfall refuses these inputs:`);
  console.error(String(err.message ?? err));
  process.exit(1);
}

const ecarts = Object.keys(attendu)
  .filter((k) => quote[k] !== undefined && quote[k] !== attendu[k])
  .map((k) => `  ${k}: fixture=${quote[k]} · pinned waterfall=${attendu[k]}`);

if (ecarts.length > 0) {
  console.error(`money-reconciliation FAILED on ${file}: the quote reconciles, but it is not what the`);
  console.error('PINNED waterfall computes from its own inputs — a fee rate or a net has drifted from canon:');
  console.error(ecarts.join('\n'));
  process.exit(1);
}

console.log(`money-reconciliation OK — ${file} reconciles to the franc AND matches the pinned waterfall (§5.4)`);
